const { notify } = useNotify()
const { lines } = useCart()
const { code } = useDiscount()

const isPlacing = ref(false)

async function placeOrder() {
  if (isPlacing.value) return
  isPlacing.value = true
  try {
    const order = await $fetch<{ id: string }>('/api/orders', {
      method: 'POST',
      body: {
        lines: lines.value,
        code: code.value,
      },
    })

    // Clear cart and discount code
    lines.value = []
    code.value = null

    // Notify
    notify(`Order placed for ${email.value}`)

    // Navigate
    await navigateTo(`/orders/${order.id}`)
  } catch (err) {
    console.error('Error placing order:', err)
  } finally {
    isPlacing.value = false
  }
}
